"use client";
// src/button.tsx
import {
  button as buttonPrimitive
} from "@ui-sdk/core/button";
import {
  renderElement,
  usePart,
  usePrimitive
} from "./use-primitive.js";
function Button({
  disabled,
  focusableWhenDisabled,
  type,
  pendingAnnouncement,
  debug,
  onClick,
  render,
  ...props
}) {
  const button = usePrimitive(buttonPrimitive, {
    disabled,
    focusableWhenDisabled,
    type,
    pendingAnnouncement,
    debug
  });
  const press = (event) => {
    button.api.internal.press(
      event.nativeEvent,
      (details) => onClick?.(event, details)
    );
    if (event.nativeEvent.defaultPrevented && !event.isDefaultPrevented()) {
      event.preventDefault();
    }
  };
  return usePart(
    button,
    "root",
    {},
    {
      ...props,
      render: (root, state) => renderElement("button", { ...root, onClick: press }, render, state)
    },
    "button"
  );
}
export {
  Button
};
